"""Prepared SG2 regressions: generated bytes, probe doubles, real worker death.

These cases exercise filesystem workflow only. They do not establish valid MP4
content, physical measurement, clinical acceptance, power-loss safety or RPO/RTO.
"""
from __future__ import annotations

import json
import os
import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

import capture_station
import session_contract
import workflow_recovery
from backup_manager import BackupCorruptError, BackupManager
from session_contract import ROLES, sha256_file
from session_index import SessionIndex
from session_library import SessionError, SessionLibrary
from workflow_recovery import RecoveryBlocked, archive_orphaned_lock, inspect_recovery

ROOT = Path(__file__).resolve().parents[1]
ROLE = "cam01_board"
PROBE = {"width": 1280, "height": 720, "rotation": 0, "duration": 15,
         "fps": "30/1", "frame_count": 450}
PRIOR = b"generated prior capture, no patient or video data"
SELECTED = b"generated selected take, no patient or video data"

WORKER = r'''
import json
import os
import sys
from pathlib import Path
from unittest.mock import patch
import session_library

projects, sid, role, selected, boundary, checkpoint = sys.argv[1:]
project = Path(projects) / sid
canonical = project / "raw" / (role + ".mp4")
copy_verified = session_library._copy_verified
replace = os.replace
retire_marker = session_library.takes.retire_marker

def die():
    record = {"boundary": boundary, "lock_exists": (project / "takes/accept.lock").is_file(),
              "canonical_sha256": session_library.sha256_file(canonical),
              "staged_sha256": session_library.sha256_file(Path(selected))}
    with Path(checkpoint).open("x", encoding="utf-8") as stream:
        json.dump(record, stream, allow_nan=False)
        stream.flush()
        os.fsync(stream.fileno())
    os._exit(73)

def copy_at_boundary(source, target):
    target = Path(target)
    if boundary == "after-lock" and target.parent.name == "archive":
        die()
    copy_verified(source, target)
    if boundary == "after-archive" and target.parent.name == "archive":
        die()
    if boundary == "after-replacement" and target.suffix == ".replacement":
        die()

def replace_at_boundary(source, target):
    if Path(target) == canonical and boundary == "before-replace":
        die()
    replace(source, target)
    if Path(target) == canonical and boundary == "after-replace":
        die()

def retire_at_boundary(transaction):
    if boundary == "after-commit":
        die()
    return retire_marker(transaction)

with patch("session_library.probe_clip", return_value={"width": 1280, "height": 720,
        "rotation": 0, "duration": 15, "fps": "30/1", "frame_count": 450}), \
     patch("session_library._copy_verified", side_effect=copy_at_boundary), \
     patch("session_library.os.replace", side_effect=replace_at_boundary), \
     patch("session_library.takes.retire_marker", side_effect=retire_at_boundary):
    session_library.SessionLibrary(Path(projects)).accept_take(sid, role, Path(selected))
raise SystemExit("fault boundary was not reached")
'''

RECOVERY_WORKER = r'''
import json
import os
import sys
from pathlib import Path
from unittest.mock import patch
import workflow_recovery

project, transaction_id, boundary, checkpoint = sys.argv[1:]
project = Path(project)
marker = project / "takes/accept.lock"
receipt = project / "takes/acceptance" / transaction_id / "recovery.json"
original_link, original_rename, original_replace, original_unlink = os.link, os.rename, os.replace, os.unlink

def die():
    if not receipt.is_file():
        raise RuntimeError("recovery receipt must precede marker retirement")
    with Path(checkpoint).open("x", encoding="utf-8") as stream:
        json.dump({"boundary": boundary, "receipt": receipt.read_text(encoding="utf-8"),
                   "marker_exists": marker.exists()}, stream, allow_nan=False)
        stream.flush()
        os.fsync(stream.fileno())
    os._exit(79)

def move(original, source, target, *args, **kwargs):
    retiring = Path(source) == marker
    if retiring and boundary == "before-marker-retirement":
        die()
    result = original(source, target, *args, **kwargs)
    if retiring and boundary == "after-marker-retirement":
        die()
    return result

def link(source, target, *args, **kwargs):
    if Path(source) == marker and boundary == "before-marker-retirement":
        die()
    return original_link(source, target, *args, **kwargs)

def unlink(path, *args, **kwargs):
    retiring = Path(path) == marker
    if retiring and boundary == "before-marker-retirement":
        die()
    result = original_unlink(path, *args, **kwargs)
    if retiring and boundary == "after-marker-retirement":
        die()
    return result

with patch("os.link", side_effect=link), \
     patch("os.rename", side_effect=lambda *a, **k: move(original_rename, *a, **k)), \
     patch("os.replace", side_effect=lambda *a, **k: move(original_replace, *a, **k)), \
     patch("os.unlink", side_effect=unlink):
    workflow_recovery.recover_take_acceptance(project, transaction_id, confirmed=True)
raise SystemExit("recovery fault boundary was not reached")
'''


class TakeAcceptanceRecoveryTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)
        self.projects = self.root / "projects"
        self.projects.mkdir()
        self.library = SessionLibrary(self.projects)

    def fixture(self, name):
        project = self.library.create_session(name)
        canonical = project / "raw" / (ROLE + ".mp4")
        canonical.write_bytes(PRIOR)
        source = self.root / (name + "-generated.mp4")
        source.write_bytes(SELECTED)
        with patch("session_library.probe_clip", return_value=PROBE):
            staged = self.library.stage_take(name, ROLE, source)
        return project, canonical, staged

    def complete_inputs(self, project):
        for role in ROLES:
            (project / "raw" / (role + ".mp4")).write_bytes(PRIOR + role.encode("ascii"))
        (project / "board-measurement.json").write_text(json.dumps({
            "source": "operator_measured_not_independently_verified", "measured_square_mm": 20,
        }), encoding="utf-8")

    def test_file_proof_accepts_a_stable_copy_with_preserved_mtime(self):
        import take_acceptance

        source, copied = self.root / "generated-source", self.root / "generated-copy"
        source.write_bytes(SELECTED)
        os.utime(source, ns=(1_000_000_000, 1_000_000_000))
        shutil.copy2(source, copied)
        proof = take_acceptance.file_proof(copied)
        self.assertEqual(proof.sha256, sha256_file(source))
        self.assertEqual(proof.size, len(SELECTED))

    def test_lease_yields_the_readable_owner_stream_and_blocks_another_process(self):
        from runtime_config import startup_lock
        from take_acceptance import acceptance_lease

        contender = ("import sys\nfrom pathlib import Path\nfrom runtime_config import startup_lock\n"
                     "try:\n with startup_lock(Path(sys.argv[1]), timeout=0):\n  raise SystemExit(7)\n"
                     "except TimeoutError:\n raise SystemExit(81)\n")
        for kind in ("runtime", "acceptance"):
            with self.subTest(kind=kind):
                project = self.root / ("owner-stream-" + kind)
                project.mkdir()
                directory = project / "takes/.acceptance-lease"
                lease = startup_lock(directory, timeout=0) if kind == "runtime" else acceptance_lease(project)
                with lease as stream:
                    self.assertIsNotNone(stream, "OS lease must expose its actual owning stream")
                    self.assertFalse(stream.closed)
                    anchor = directory / "t6-startup.lock"
                    self.assertEqual(Path(stream.name), anchor)
                    owned = os.fstat(stream.fileno())
                    by_path = anchor.stat()
                    self.assertEqual((owned.st_dev, owned.st_ino), (by_path.st_dev, by_path.st_ino))
                    stream.seek(0)
                    self.assertEqual(stream.read(), b"0")
                    child = subprocess.run([sys.executable, "-B", "-c", contender, str(directory)],
                                           cwd=ROOT, capture_output=True, text=True, encoding="utf-8",
                                           timeout=30, check=False)
                    self.assertEqual(child.returncode, 81, child.stderr)
                self.assertTrue(stream.closed)
                self.assertEqual(anchor.read_bytes(), b"0")
                # Existing callers that do not bind a context result remain compatible.
                with startup_lock(directory, timeout=0):
                    self.assertTrue(anchor.is_file())

    def tree_snapshot(self, project):
        return {path.relative_to(project).as_posix(): path.read_bytes() if path.is_file() else None
                for path in sorted(project.rglob("*"))}

    def recover(self, project, transaction_id, *, confirmed):
        method = getattr(workflow_recovery, "recover_take_acceptance", None)
        self.assertTrue(callable(method), "Operator recovery must be an explicit guarded public API")
        return method(project, transaction_id, confirmed=confirmed)

    def crashed_transaction(self, name, boundary="after-archive", *, prior=PRIOR):
        project, canonical, staged = self.fixture(name)
        canonical.write_bytes(prior)
        checkpoint = self.root / (name + "-acceptance.json")
        child = subprocess.run(
            [sys.executable, "-B", "-c", WORKER, str(self.projects), project.name,
             ROLE, str(staged), boundary, str(checkpoint)], cwd=ROOT,
            text=True, encoding="utf-8", capture_output=True, timeout=60, check=False,
        )
        self.assertEqual(child.returncode, 73, child.stderr)
        intents = list((project / "takes/acceptance").glob("*/intent.json"))
        self.assertEqual(len(intents), 1, "Interrupted acceptance needs exactly one immutable intent")
        intent = json.loads(intents[0].read_text(encoding="utf-8"))
        self.assertEqual(intent["transaction_id"], intents[0].parent.name)
        return project, canonical, staged, intents[0], intent["transaction_id"]

    def test_committed_lost_response_recovers_even_when_prior_equals_selected(self):
        for number, prior in enumerate((PRIOR, SELECTED)):
            with self.subTest(identical=prior == SELECTED):
                project, canonical, staged, intent_path, transaction_id = self.crashed_transaction(
                    f"committed-response-{number}", "after-commit", prior=prior)
                commit = intent_path.parent / "commit.json"
                committed_bytes = commit.read_bytes()
                self.assertTrue((project / "takes/accept.lock").is_file())
                result = self.recover(project, transaction_id, confirmed=True)
                self.assertEqual(result["outcome"], "selected-verified")
                self.assertEqual(canonical.read_bytes(), SELECTED)
                self.assertEqual(staged.read_bytes(), SELECTED)
                self.assertEqual(commit.read_bytes(), committed_bytes)
                self.assertFalse((intent_path.parent / "recovery.json").exists())
                self.assertFalse((project / "takes/accept.lock").exists())

    def test_process_death_is_visible_without_promoting_or_discarding_artifacts(self):
        boundaries = ("after-lock", "after-archive", "after-replacement", "before-replace", "after-replace")
        for boundary in boundaries:
            with self.subTest(boundary=boundary):
                project, canonical, staged = self.fixture("death-" + boundary)
                selected_digest = sha256_file(staged)
                prior_digest = sha256_file(canonical)
                checkpoint = self.root / (boundary + ".json")
                child = subprocess.run(
                    [sys.executable, "-B", "-c", WORKER, str(self.projects), project.name,
                     ROLE, str(staged), boundary, str(checkpoint)], cwd=ROOT,
                    text=True, encoding="utf-8", capture_output=True, timeout=60, check=False,
                )
                self.assertEqual(child.returncode, 73, child.stderr)
                observed = json.loads(checkpoint.read_text(encoding="utf-8"))
                self.assertEqual(observed["boundary"], boundary)
                self.assertTrue(observed["lock_exists"])
                self.assertEqual(sha256_file(staged), selected_digest)
                self.assertEqual(sha256_file(canonical),
                                 selected_digest if boundary == "after-replace" else prior_digest)
                if boundary != "after-lock":
                    archives = list((project / "takes/archive").glob(ROLE + "-*.mp4"))
                    self.assertEqual(len(archives), 1)
                    self.assertEqual(sha256_file(archives[0]), prior_digest)
                self.assertFalse((project / "session.json").exists())
                lock_bytes = (project / "takes/accept.lock").read_bytes()
                with patch("session_library.probe_clip", return_value=PROBE), \
                     self.assertRaisesRegex(SessionError, "TAKE_BUSY|TAKE_RECOVERY"):
                    self.library.accept_take(project.name, ROLE, staged)
                state = inspect_recovery(project)
                take = state["locks"].get("takes/accept.lock")
                self.assertIsInstance(take, dict, "Interrupted take acceptance must appear in recovery diagnostics")
                self.assertIn(take["state"], {"unknown", "interrupted", "recovery-required"})
                self.assertFalse(state["native_run_passed"])
                self.assertEqual((project / "takes/accept.lock").read_bytes(), lock_bytes)

    def test_backup_refuses_acceptance_markers_before_index_or_archive_publication(self):
        markers = ("takes/accept.lock", "raw/." + ROLE + "-" + "a" * 32 + ".replacement")
        for number, name in enumerate(markers):
            with self.subTest(marker=name):
                project, canonical, staged = self.fixture("busy-" + str(number))
                index = SessionIndex(self.projects / ".kinelab_index.db", self.projects)
                try:
                    index.reindex()
                    prior_audit = index.verify_audit()
                    marker = project / name
                    marker.parent.mkdir(parents=True, exist_ok=True)
                    marker.write_bytes(b"generated interrupted acceptance marker")
                    target = self.root / ("blocked-" + str(number) + ".zip")
                    with self.assertRaisesRegex(BackupCorruptError, "BACKUP_BUSY"):
                        BackupManager(self.projects, index).create_backup(target)
                    self.assertFalse(target.exists())
                    self.assertEqual(index.verify_audit(), prior_audit)
                    self.assertEqual(canonical.read_bytes(), PRIOR)
                    self.assertEqual(staged.read_bytes(), SELECTED)
                    self.assertTrue(marker.is_file())
                finally:
                    index.close()
                    marker.unlink(missing_ok=True)

    def test_pending_acceptance_blocks_registration_readiness(self):
        project, _, _ = self.fixture("registration-fence")
        for role in ROLES:
            (project / "raw" / (role + ".mp4")).write_bytes(PRIOR + role.encode("ascii"))
        (project / "board-measurement.json").write_text(json.dumps({
            "source": "operator_measured_not_independently_verified", "measured_square_mm": 20,
        }), encoding="utf-8")
        (project / "takes/accept.lock").write_text("987654321", encoding="utf-8")
        with patch("capture_station.probe_clip", return_value=PROBE):
            readiness = self.library.registration_readiness(project.name)
        self.assertFalse(readiness["ready_to_register"], "Pending take selection cannot become a registered generation")
        self.assertTrue(any("TAKE" in str(issue).upper() for issue in readiness["issues"]))
        self.assertFalse((project / "session.json").exists())

    def test_pending_acceptance_blocks_registration_write(self):
        project, _, _ = self.fixture("registration-write")
        for role in ROLES:
            (project / "raw" / (role + ".mp4")).write_bytes(PRIOR + role.encode("ascii"))
        (project / "board-measurement.json").write_text(json.dumps({
            "source": "operator_measured_not_independently_verified", "measured_square_mm": 20,
        }), encoding="utf-8")
        (project / "takes/accept.lock").write_text("987654321", encoding="utf-8")
        with patch("capture_station.probe_clip", return_value=PROBE), self.assertRaises(SessionError):
            self.library.register_session(project.name)
        self.assertFalse((project / "session.json").exists())

    def test_legacy_and_unknown_take_locks_remain_preserved_even_with_dead_pid(self):
        values = (b"987654321", b"", b"unrecognized-owner", b'{"schema":"unknown"}')
        for number, value in enumerate(values):
            with self.subTest(value=value):
                project, canonical, staged = self.fixture("unknown-" + str(number))
                lock = project / "takes/accept.lock"
                lock.write_bytes(value)
                with patch("workflow_recovery.psutil.pid_exists", return_value=False), \
                     patch("workflow_recovery._related_processes", return_value=[]):
                    with self.assertRaises(RecoveryBlocked):
                        archive_orphaned_lock(project, "takes/accept.lock", confirmed=True)
                    self.assertEqual(lock.read_bytes(), value)
                    self.assertEqual(canonical.read_bytes(), PRIOR)
                    self.assertEqual(staged.read_bytes(), SELECTED)
                    status = inspect_recovery(project)["locks"].get("takes/accept.lock")
                    self.assertIsInstance(status, dict, "Unsupported acceptance lock must be reported, never guessed absent")
                    self.assertEqual(status["state"], "unknown")

    def test_staged_bytes_changed_during_probe_are_not_published(self):
        project, canonical, staged = self.fixture("changed-staged")
        def probe_then_change(_):
            staged.write_bytes(b"changed generated bytes after metadata observation")
            return PROBE
        with patch("session_library.probe_clip", side_effect=probe_then_change), \
             self.assertRaisesRegex(SessionError, "INPUT_CHANGED|TAKE_INPUT_CHANGED|TAKE_TRANSACTION"):
            self.library.accept_take(project.name, ROLE, staged)
        self.assertEqual(canonical.read_bytes(), PRIOR)
        self.assertFalse((project / "session.json").exists())

    def test_canonical_change_after_archive_is_not_silently_overwritten(self):
        project, canonical, staged = self.fixture("changed-canonical")
        import session_library
        copy_verified = session_library._copy_verified
        changed = b"concurrent generated canonical bytes that have not been archived"
        def copy_then_change(source, target):
            copy_verified(source, target)
            if Path(target).suffix == ".replacement":
                canonical.write_bytes(changed)
        with patch("session_library.probe_clip", return_value=PROBE), \
             patch("session_library._copy_verified", side_effect=copy_then_change), \
             self.assertRaisesRegex(SessionError, "INPUT_CHANGED|TAKE_INPUT_CHANGED|TAKE_TRANSACTION"):
            self.library.accept_take(project.name, ROLE, staged)
        self.assertEqual(canonical.read_bytes(), changed)
        archives = list((project / "takes/archive").glob(ROLE + "-*.mp4"))
        self.assertEqual(len(archives), 1)
        self.assertEqual(archives[0].read_bytes(), PRIOR)
        self.assertEqual(staged.read_bytes(), SELECTED)

    def test_direct_registration_cannot_bypass_pending_acceptance(self):
        from setup_project import register_captures
        project, _, _ = self.fixture("direct-register")
        self.complete_inputs(project)
        (project / "takes/accept.lock").write_bytes(b"987654321")
        with self.assertRaisesRegex(ValueError, "TAKE"):
            register_captures(project, project.name)
        self.assertFalse((project / "session.json").exists())

    def test_direct_readiness_cannot_bypass_pending_acceptance(self):
        project, _, _ = self.fixture("direct-ready")
        self.complete_inputs(project)
        marker = project / "takes/accept.lock"
        marker.write_bytes(b"987654321")
        with patch("capture_station.probe_clip", return_value=PROBE):
            result = capture_station.check_readiness(project)
        self.assertFalse(result["ready_to_register"])
        self.assertTrue(any("TAKE" in str(issue).upper() for issue in result["issues"]))
        self.assertEqual(marker.read_bytes(), b"987654321")

    def test_direct_capture_publication_preserves_pending_acceptance(self):
        for method in ("import", "finalize"):
            with self.subTest(method=method):
                project, canonical, staged = self.fixture("direct-publish-" + method)
                marker = project / "takes/accept.lock"
                marker.write_bytes(b"987654321")
                if method == "import":
                    source = self.root / "generated-import.mp4"
                    source.write_bytes(SELECTED)
                    operation = lambda project=project, source=source: capture_station.import_phone_mp4(project, "cam01_intrinsics", source)
                    target = project / "raw/cam01_intrinsics.mp4"
                else:
                    partial = project / "raw/cam02_board.part.mp4"
                    partial.write_bytes(SELECTED)
                    operation = lambda project=project: capture_station.finalize_recording(project, "cam02_board")
                    target = project / "raw/cam02_board.mp4"
                with patch("capture_station.probe_clip", return_value=PROBE), \
                     self.assertRaisesRegex(ValueError, "TAKE"):
                    operation()
                self.assertFalse(target.exists())
                self.assertEqual(canonical.read_bytes(), PRIOR)
                self.assertEqual(staged.read_bytes(), SELECTED)
                self.assertEqual(marker.read_bytes(), b"987654321")
                if method == "finalize":
                    self.assertEqual(partial.read_bytes(), SELECTED)

    def test_direct_session_validation_rejects_a_pending_transaction(self):
        project, _, _ = self.fixture("direct-validation")
        self.complete_inputs(project)
        data = {"schema": "kinelab.session.v1", "session_id": project.name,
                "kind": "real", "subject_count": 1, "camera_ids": ["cam01", "cam02"],
                "created_at": "2026-10-29T00:00:00+00:00", "captures": {
                    role: {"path": "raw/" + role + ".mp4",
                           "sha256": sha256_file(project / "raw" / (role + ".mp4"))}
                    for role in ROLES}}
        (project / "session.json").write_text(json.dumps(data), encoding="utf-8")
        (project / "takes/accept.lock").write_bytes(b"987654321")
        for reader in (lambda: session_contract.validate_session(data, project),
                       lambda: session_contract.load_session(project)):
            with self.subTest(reader=reader), self.assertRaisesRegex(ValueError, "TAKE"):
                reader()

    def test_new_staging_refuses_an_interrupted_acceptance(self):
        project, canonical, staged = self.fixture("stage-fence")
        (project / "takes/accept.lock").write_bytes(b"987654321")
        prior_staged = list((project / "takes" / ROLE).iterdir())
        with patch("session_library.probe_clip", return_value=PROBE), \
             self.assertRaisesRegex(SessionError, "TAKE"):
            self.library.stage_take(project.name, ROLE, staged)
        self.assertEqual(list((project / "takes" / ROLE).iterdir()), prior_staged)
        self.assertEqual(canonical.read_bytes(), PRIOR)

    def test_operator_recovery_requires_exact_true_before_any_mutation(self):
        project, _, _ = self.fixture("confirm-recovery")
        (project / "takes/accept.lock").write_bytes(b"987654321")
        before = self.tree_snapshot(project)
        for confirmed in (False, None, 0, 1, "true", [], {}):
            with self.subTest(confirmed=confirmed), \
                 self.assertRaisesRegex(RecoveryBlocked, "TAKE_RECOVERY_CONFIRMATION_REQUIRED"):
                self.recover(project, "a" * 32, confirmed=confirmed)
            self.assertEqual(self.tree_snapshot(project), before)

    def test_operator_recovery_refuses_unknown_and_ambiguous_markers(self):
        values = (b"987654321", b"", b'{"schema":"unknown"}',
                  b'{"transaction_id":"a","transaction_id":"b"}',
                  b'{"score":NaN}', b'{"score":1e9999}')
        for number, value in enumerate(values):
            with self.subTest(marker=value):
                project, _, _ = self.fixture("unknown-recover-" + str(number))
                (project / "takes/accept.lock").write_bytes(value)
                lease = project / "takes/.acceptance-lease/t6-startup.lock"
                lease.parent.mkdir(parents=True, exist_ok=True)
                lease.write_bytes(b"0")
                before = self.tree_snapshot(project)
                with self.assertRaisesRegex(RecoveryBlocked, "TAKE_RECOVERY_UNKNOWN"):
                    self.recover(project, "a" * 32, confirmed=True)
                self.assertEqual(self.tree_snapshot(project), before)

    def test_operator_recovery_preserves_prior_or_verified_selected_bytes(self):
        for boundary, outcome, expected in (("after-archive", "previous-preserved", PRIOR),
                                            ("after-replace", "selected-verified", SELECTED)):
            with self.subTest(boundary=boundary):
                project, canonical, staged, intent_path, transaction_id = self.crashed_transaction(
                    "recover-" + boundary, boundary)
                intent_bytes = intent_path.read_bytes()
                result = self.recover(project, transaction_id, confirmed=True)
                self.assertEqual(set(result), {
                    "session_id", "transaction_id", "role", "outcome", "canonical_sha256",
                    "prior_sha256", "archives_retained", "artifacts_quarantined",
                    "native_run_passed", "clinical_validation"})
                self.assertEqual(result["outcome"], outcome)
                self.assertEqual(result["transaction_id"], transaction_id)
                self.assertEqual(result["session_id"], project.name)
                self.assertEqual(result["role"], ROLE)
                self.assertEqual(result["canonical_sha256"], sha256_file(canonical))
                self.assertTrue(result["archives_retained"])
                self.assertFalse(result["native_run_passed"])
                self.assertEqual(result["clinical_validation"], "UNVERIFIED")
                self.assertEqual(canonical.read_bytes(), expected)
                self.assertEqual(staged.read_bytes(), SELECTED)
                self.assertEqual(intent_path.read_bytes(), intent_bytes)
                self.assertEqual((project / "takes/archive" / (ROLE + "-" + transaction_id + ".mp4")).read_bytes(), PRIOR)
                self.assertFalse((project / "takes/accept.lock").exists())
                self.assertTrue((intent_path.parent / "recovery.json").is_file())
                self.assertTrue((intent_path.parent / "accept.lock.archived").is_file())
                self.assertFalse((project / "session.json").exists())

    def test_operator_recovery_refuses_changed_or_missing_proof(self):
        for fault in ("canonical", "staged", "archive", "missing-archive", "intent", "multiple"):
            with self.subTest(fault=fault):
                project, canonical, staged, intent_path, transaction_id = self.crashed_transaction(
                    "recovery-proof-" + fault, "after-replace")
                archive = project / "takes/archive" / (ROLE + "-" + transaction_id + ".mp4")
                if fault == "canonical":
                    canonical.write_bytes(b"unknown generated canonical bytes")
                elif fault == "staged":
                    staged.write_bytes(b"unknown generated staged bytes")
                elif fault == "archive":
                    archive.write_bytes(b"unknown generated archive bytes")
                elif fault == "missing-archive":
                    archive.unlink()
                elif fault == "intent":
                    intent = json.loads(intent_path.read_text(encoding="utf-8"))
                    intent["staged_sha256"] = "d" * 64
                    intent_path.write_text(json.dumps(intent), encoding="utf-8")
                else:
                    intent = json.loads(intent_path.read_text(encoding="utf-8"))
                    intent["transaction_id"] = "e" * 32
                    extra = intent_path.parent.parent / ("e" * 32)
                    extra.mkdir()
                    (extra / "intent.json").write_text(json.dumps(intent), encoding="utf-8")
                before = self.tree_snapshot(project)
                with self.assertRaisesRegex(RecoveryBlocked, "TAKE_RECOVERY_(UNKNOWN|CHANGED)"):
                    self.recover(project, transaction_id, confirmed=True)
                self.assertEqual(self.tree_snapshot(project), before)

    def test_operator_recovery_repeat_and_old_terminal_cannot_authorize_new_paths(self):
        project, canonical, staged, intent_path, transaction_id = self.crashed_transaction("old-terminal")
        self.recover(project, transaction_id, confirmed=True)
        terminal = (intent_path.parent / "recovery.json").read_bytes()
        before = self.tree_snapshot(project)
        with self.assertRaisesRegex(RecoveryBlocked, "TAKE_RECOVERY_NO_PENDING"):
            self.recover(project, transaction_id, confirmed=True)
        self.assertEqual(self.tree_snapshot(project), before)
        canonical.write_bytes(b"later generated canonical bytes")
        staged.write_bytes(b"later generated staged bytes at reused historical path")
        before = self.tree_snapshot(project)
        with self.assertRaisesRegex(RecoveryBlocked, "TAKE_RECOVERY_NO_PENDING"):
            self.recover(project, transaction_id, confirmed=True)
        self.assertEqual(self.tree_snapshot(project), before)
        self.assertEqual((intent_path.parent / "recovery.json").read_bytes(), terminal)

    def test_second_process_death_during_recovery_is_repeatable(self):
        for boundary in ("before-marker-retirement", "after-marker-retirement"):
            with self.subTest(boundary=boundary):
                project, canonical, staged, intent_path, transaction_id = self.crashed_transaction(
                    "second-death-" + boundary)
                checkpoint = self.root / ("recovery-" + boundary + ".json")
                child = subprocess.run(
                    [sys.executable, "-B", "-c", RECOVERY_WORKER, str(project), transaction_id,
                     boundary, str(checkpoint)], cwd=ROOT, text=True, encoding="utf-8",
                    capture_output=True, timeout=60, check=False,
                )
                self.assertEqual(child.returncode, 79, child.stderr)
                observed = json.loads(checkpoint.read_text(encoding="utf-8"))
                self.assertEqual(observed["boundary"], boundary)
                receipt = (intent_path.parent / "recovery.json").read_bytes()
                if boundary == "before-marker-retirement":
                    self.assertTrue(observed["marker_exists"])
                    self.assertEqual(self.recover(project, transaction_id, confirmed=True)["outcome"],
                                     "previous-preserved")
                else:
                    self.assertFalse(observed["marker_exists"])
                    with self.assertRaisesRegex(RecoveryBlocked, "TAKE_RECOVERY_NO_PENDING"):
                        self.recover(project, transaction_id, confirmed=True)
                self.assertEqual((intent_path.parent / "recovery.json").read_bytes(), receipt)
                self.assertEqual(canonical.read_bytes(), PRIOR)
                self.assertEqual(staged.read_bytes(), SELECTED)
                self.assertFalse((project / "takes/accept.lock").exists())

    def test_acceptance_finalizer_does_not_retire_a_successor_marker(self):
        import session_library
        project, canonical, staged = self.fixture("successor-marker")
        marker = project / "takes/accept.lock"
        successor = b'{"schema":"unknown-successor","owner":"generated"}'
        replace = session_library.os.replace
        def replace_then_successor(source, target):
            replace(source, target)
            if Path(target) == canonical:
                marker.write_bytes(successor)
        with patch("session_library.probe_clip", return_value=PROBE), \
             patch("session_library.os.replace", side_effect=replace_then_successor), \
             self.assertRaisesRegex(SessionError, "TAKE"):
            self.library.accept_take(project.name, ROLE, staged)
        self.assertEqual(marker.read_bytes(), successor)
        self.assertEqual(canonical.read_bytes(), SELECTED)

